mapper.select:
SELECT ai.*, al.modify_time AS terminateOperationDate, al.modify_by AS terminateOperation, wo.id AS workOrderId FROM asset_info ai LEFT JOIN ( SELECT *, row_number()over(partition by asset_uid order by create_time desc) FROM asset_lifecycle WHERE current_status = 4 AND tenant_uid = #{tenantUid} ) al ON ai.uid = al.asset_uid AND al.row_number = 1 LEFT JOIN ( SELECT id, asset_id, row_number()over(partition by asset_id order by created_date desc) FROM v2_work_order WHERE tenant_uid = #{tenantUid} AND status = 1 ) wo ON ai.id = wo.asset_id AND wo.row_number = 1
${orderBy}
LIMIT #{page} OFFSET #{offset}

select ai.id, ai.uid, ai.name, ai.status, ai.tenant_uid, ai.institution_uid, ai.hospital_uid, ai.site_uid, ai.financing_num, ai.serial_num, ai.depart_num, ai.qr_code, ai.asset_dept_uid, ai.clinical_dept_uid from org_info oi, user_org uo, asset_info ai

    uo.user_uid = #{userUid}
    AND ai.tenant_uid = #{tenantUid}
    AND uo.org_uid IN ( oi.tenant_uid, oi.hospital_uid, oi.site_uid, oi.institution_uid, oi.uid )
    AND oi.org_type = 3
    AND oi.uid= ai.site_uid
    and ai.is_deleted='false' and ai.is_valid='true'

        and ai.site_uid = #{siteUid}


        and ai.clinical_dept_uid = #{clinicalDeptUid}


        and ai.asset_group = #{assetGroup}


        and (ai.name like concat('%',#{oneSearchStr},'%') or ai.depart_num like concat('%',#{oneSearchStr},'%') or ai.financing_num like concat('%',#{oneSearchStr},'%') or ai.qr_code like concat('%',#{oneSearchStr},'%') or ai.serial_num like concat('%',#{oneSearchStr},'%') )


limit 1000 offset 0

select ai.id, ai.uid, ai.name, ai.tenant_uid, ai.institution_uid, ai.hospital_uid, ai.site_uid, ai.financing_num, ai.serial_num, ai.depart_num, ai.qr_code, ai.asset_dept_uid, ai.clinical_dept_uid from org_info oi, user_org uo, asset_info ai

    uo.user_uid = #{userUid}
    AND ai.tenant_uid = #{tenantUid}
    AND uo.org_uid IN ( oi.tenant_uid, oi.hospital_uid, oi.site_uid, oi.institution_uid, oi.uid )
    AND oi.org_type = 3
    AND oi.uid= ai.site_uid
    and ai.is_deleted='false' and ai.is_valid='true'

        and ai.site_uid = #{siteUid}


        and ai.clinical_dept_uid = #{clinicalDeptUid}


        and ai.asset_group = #{assetGroup}


        and (ai.name like concat('%',#{oneSearchStr},'%') or ai.depart_num like concat('%',#{oneSearchStr},'%') or ai.financing_num like concat('%',#{oneSearchStr},'%') or ai.qr_code like concat('%',#{oneSearchStr},'%') or ai.serial_num like concat('%',#{oneSearchStr},'%') )


limit 1000 offset 0

